CREATE TABLE resources (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT 'other',
  organization TEXT,
  phone TEXT,
  fax TEXT,
  email TEXT,
  website TEXT,
  address TEXT,
  city TEXT,
  zip TEXT,
  hours TEXT,
  eligibility TEXT,
  services TEXT,
  languages TEXT,
  accepts_medicaid INTEGER DEFAULT 0,
  accepts_uninsured INTEGER DEFAULT 0,
  mat_offered TEXT,
  capacity_notes TEXT,
  contact_person TEXT,
  summary TEXT,                         -- plain-language overview shown on the profile
  service_tags TEXT,                    -- comma separated SERVICE_TAGS
  levels_of_care TEXT,                  -- comma separated ASAM levels
  populations TEXT,                     -- who they serve (comma separated POPULATIONS)
  intake_process TEXT,
  cost_notes TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  last_verified_at TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('29643c31-d956-4ed0-a21c-dcaf533b8f78','County OTP','mat_otp',NULL,'555-0199',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,'2026-09-26T23:20:31.179Z','2026-09-26T23:20:31.179Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('6613d4b9-1c86-43ca-a59c-5650ba79f94f','Riverside Recovery Center','residential',NULL,'555-0200',NULL,NULL,'https://example.org/riverside-recovery-center','200 Sample Ave','Springfield','00000','Mon–Fri 8–5; intake line 24/7',NULL,'28-day residential; medically supervised. Adults 18+.','English, Spanish',1,1,'buprenorphine, naltrexone',NULL,NULL,'A 42-bed residential program on the river with medical staff on site around the clock. Clients start with a medical assessment and, if needed, medically supervised withdrawal, then move into a structured 28-day program of group and individual counseling, MAT (buprenorphine or naltrexone), family sessions and discharge planning. Most clients step down to Northside IOP or Bridge Housing.','residential,detox,mat_buprenorphine,mat_naltrexone,individual_counseling,group_counseling,family_program,co_occurring,aftercare,spanish_speaking','3.5, 3.7','adults,women,men,justice_involved','Call the intake line any time; a nurse screens by phone in about 20 minutes. Bring ID and insurance card if you have them; neither is required to be admitted. Beds are usually available within 1–3 days.','Medicaid and most commercial plans; county-funded beds for uninsured residents.',1,'2026-09-25','Sample resource (fictional)','2026-09-26T23:20:31.726Z','2026-09-26T23:20:31.726Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('733b3778-82e0-4f0b-af90-a625c6bcb1b3','County Opioid Treatment Program','mat_otp',NULL,'555-0201',NULL,NULL,'https://example.org/county-opioid-treatment-program','240 Sample Ave','Springfield','00000','Dosing 5:30am–11am daily',NULL,'Methadone and buprenorphine; same-day intake Tue/Thu.','English, Spanish',1,1,'methadone, buprenorphine',NULL,NULL,'The county''s licensed opioid treatment program. Daily observed methadone or buprenorphine dosing with take-home doses earned over time, plus counseling, peer support and on-site naloxone. Same-day intake on Tuesdays and Thursdays for anyone who arrives before 9am.','mat_methadone,mat_buprenorphine,medication_management,individual_counseling,group_counseling,peer_support,naloxone,same_day_intake,walk_in,spanish_speaking','OTP','adults,pregnant_parenting,justice_involved','Walk in Tue/Thu before 9am with a photo ID if possible. A navigator warm handoff speeds things up: call the intake nurse the day before.','Medicaid covers dosing in full; sliding scale for uninsured (about $15/week).',1,'2026-07-01','Sample resource (fictional)','2026-09-26T23:20:31.847Z','2026-09-26T23:20:31.847Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('00953a9b-e7fa-4b4f-b82c-9f4b3cfa1f54','Hope Street Detox','detox_withdrawal_mgmt',NULL,'555-0202',NULL,NULL,'https://example.org/hope-street-detox','280 Sample Ave','Springfield','00000','24/7',NULL,'Social and medical detox; call for bed availability.','English',1,1,NULL,NULL,NULL,'Short-stay (3–7 day) withdrawal management with nursing 24/7 and a physician on call. Comfort medications for opioid, alcohol and benzodiazepine withdrawal. Staff connect every client to a next step before discharge.','detox,medical_care,naloxone,crisis_24_7,aftercare','3.2, 3.7','adults','Call for bed availability; if a bed is open the client can come the same day. Ambulance or navigator transport is fine.','No cost to county residents.',1,'2026-08-11','Sample resource (fictional)','2026-09-26T23:20:31.876Z','2026-09-26T23:20:31.876Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('dcfcb9ad-bb71-4bad-b8b5-e0efabfb542d','Bridge Housing Collaborative','sober_living',NULL,'555-0203',NULL,NULL,'https://example.org/bridge-housing-collaborative','320 Sample Ave','Springfield','00000','Mon–Fri 9–4',NULL,'Recovery housing; 30 days sober required.','English',1,0,NULL,NULL,NULL,'Shared recovery homes (2–3 people per room) with house managers, weekly house meetings and required recovery-meeting attendance. Residents may stay up to 12 months while they work, study or attend treatment.','sober_living,housing,peer_support,employment,aftercare',NULL,'adults,men,women','Application plus a short interview; 30 days of sobriety and a referral from a treatment provider or navigator are required.','Rent $450/month; first month can be covered by the housing assistance line.',1,'2026-08-16','Sample resource (fictional)','2026-09-26T23:20:31.905Z','2026-09-26T23:20:31.905Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('a85d1d96-4844-4aaa-a720-e9cd154e6809','Downtown Shelter','shelter',NULL,'555-0204',NULL,NULL,'https://example.org/downtown-shelter','360 Sample Ave','Springfield','00000','Check-in 6pm',NULL,'Emergency shelter; low-barrier; pets allowed.','English, Spanish',0,1,NULL,NULL,NULL,'Low-barrier overnight shelter with 120 beds, showers, lockers and a hot dinner. Sobriety is not required. Case managers on site help with IDs, benefits and housing applications.','housing,case_management,walk_in,harm_reduction,naloxone',NULL,'adults,unhoused,veterans','Walk in at 6pm; no referral needed.','Free.',1,'2026-08-08','Sample resource (fictional)','2026-09-26T23:20:31.926Z','2026-09-26T23:20:31.926Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('a05d7aa8-e456-42a3-b4e7-3c48c48508a7','Community Harm Reduction Coalition','syringe_services',NULL,'555-0205',NULL,NULL,'https://example.org/community-harm-reduction-coalition','400 Sample Ave','Springfield','00000','Tue/Thu 1–5; mobile van Sat',NULL,'Syringe services, naloxone, fentanyl test strips, wound care.','English, Spanish',0,1,NULL,NULL,NULL,'Peer-run harm reduction center and mobile van. Free naloxone, fentanyl and xylazine test strips, safer-use supplies, wound care by a nurse, HIV/HCV testing and a warm, no-judgment place to sit down.','harm_reduction,naloxone,syringe_services,medical_care,peer_support,walk_in,spanish_speaking',NULL,'adults,unhoused,lgbtq','No referral or ID needed. The van schedule is posted on their website weekly.','Free.',1,'2026-09-03','Sample resource (fictional)','2026-09-26T23:20:31.937Z','2026-09-26T23:20:31.937Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('977b201c-8050-48b2-8761-76a140d3fa2a','Valley Behavioral Health','mental_health',NULL,'555-0206',NULL,NULL,'https://example.org/valley-behavioral-health','440 Sample Ave','Springfield','00000','Mon–Fri 8–6',NULL,'Outpatient mental health; co-occurring track.','English',1,0,NULL,NULL,NULL,'Community mental health center with psychiatry, therapy and a co-occurring disorders track for people managing both substance use and mental health conditions. Telehealth available.','mental_health,co_occurring,medication_management,individual_counseling,group_counseling,telehealth,trauma_informed','1.0','adults,adolescents,families','Phone intake, then an assessment within two weeks. Navigators can request an expedited slot for clients leaving detox or jail.','Medicaid and commercial insurance; county contract covers uninsured residents.',1,'2026-07-20','Sample resource (fictional)','2026-09-26T23:20:31.953Z','2026-09-26T23:20:31.953Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('05e5dee6-d76e-48ee-a4f4-af59bb5dfd6b','Second Chance Legal Aid','legal',NULL,'555-0207',NULL,NULL,'https://example.org/second-chance-legal-aid','480 Sample Ave','Springfield','00000','Wed 10–2 walk-in',NULL,'Expungement, warrants, benefits appeals.','English',0,1,NULL,NULL,NULL,'Free civil legal help for people in recovery: expungement, clearing warrants, driver''s license reinstatement, benefits appeals and landlord issues.','legal_help,walk_in',NULL,'adults,justice_involved','Walk in Wednesdays or call for an appointment.','Free.',1,'2026-09-09','Sample resource (fictional)','2026-09-26T23:20:31.958Z','2026-09-26T23:20:31.958Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('7e9aeed1-c4e4-402f-8bca-f61fd9e5f228','Family Health Clinic (OBOT)','mat_obot',NULL,'555-0208',NULL,NULL,'https://example.org/family-health-clinic-obot-','520 Sample Ave','Springfield','00000','Mon–Sat 8–8',NULL,'Office-based buprenorphine; telehealth follow-ups.','English, Spanish, Vietnamese',1,1,'buprenorphine',NULL,NULL,'Primary care clinic that prescribes buprenorphine as part of regular medical care, so clients can get their MAT, blood pressure and prenatal care in one place. Telehealth follow-ups after the first visit.','mat_buprenorphine,medical_care,telehealth,medication_management,spanish_speaking','1.0','adults,pregnant_parenting,families','Call for a same-week new-patient visit; bring a medication list. A navigator can attend the first visit.','Medicaid, Medicare and commercial plans; sliding scale for uninsured.',1,'2026-08-31','Sample resource (fictional)','2026-09-26T23:20:31.967Z','2026-09-26T23:20:31.967Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('af0891ba-4f96-4938-823d-eca087616c3f','Recovery Rides','transportation',NULL,'555-0209',NULL,NULL,'https://example.org/recovery-rides','560 Sample Ave','Springfield','00000','Book 24h ahead',NULL,'Free rides to treatment and court.','English',0,1,NULL,NULL,NULL,'Volunteer drivers give free rides to treatment appointments, court dates, dosing and recovery meetings within the county.','transportation',NULL,'adults','Book by phone or online at least 24 hours ahead; same-day rides when a driver is free.','Free.',1,'2026-08-31','Sample resource (fictional)','2026-09-26T23:20:31.981Z','2026-09-26T23:20:31.981Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('bd15946a-5767-4592-bc9c-7dd3b07fb3b8','Northside IOP','intensive_outpatient',NULL,'555-0210',NULL,NULL,'https://example.org/northside-iop','600 Sample Ave','Springfield','00000','Evenings Mon/Wed/Thu',NULL,'Intensive outpatient; evening groups for working adults.','English',1,0,NULL,NULL,NULL,'Nine hours a week of evening group therapy plus a weekly individual session, designed for people who work or care for children during the day. Eight to twelve weeks, followed by an aftercare group.','intensive_outpatient,group_counseling,individual_counseling,aftercare,family_program','2.1','adults,men,women','Phone screening, then an assessment within a week. Referrals from residential programs are prioritised.','Medicaid and commercial insurance.',1,'2026-09-04','Sample resource (fictional)','2026-09-26T23:20:31.987Z','2026-09-26T23:20:31.987Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('263d83aa-97ca-4e83-a5bf-f616c4231f78','County Crisis Line','crisis_line',NULL,'988',NULL,NULL,'https://example.org/county-crisis-line','640 Sample Ave','Springfield','00000','24/7',NULL,'Mobile crisis team dispatch.','English, Spanish',1,1,NULL,NULL,NULL,'Call or text 988 any time. Counselors can dispatch the mobile crisis team, which comes to the person instead of sending police, and can arrange a same-day crisis bed.','crisis_24_7,mental_health,co_occurring,spanish_speaking',NULL,'adults,adolescents','Call or text 988.','Free.',1,'2026-09-09','Sample resource (fictional)','2026-09-26T23:20:31.998Z','2026-09-26T23:20:31.998Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('66cc6e8c-7591-40f1-99a2-4d5e3477e3a4','Hands & Hearts Food Pantry','food',NULL,'555-0212',NULL,NULL,'https://example.org/hands-hearts-food-pantry','680 Sample Ave','Springfield','00000','Sat 9–12',NULL,'Groceries and hot meals; no ID required.','English',0,1,NULL,NULL,NULL,'Weekly groceries, hot meals on Saturdays and hygiene supplies. No ID or paperwork.','walk_in',NULL,'adults,families,unhoused','Walk in Saturday mornings.','Free.',1,'2026-09-13','Sample resource (fictional)','2026-09-26T23:20:31.998Z','2026-09-26T23:20:31.998Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('3f84edcd-884a-44a9-bb61-ba3c34929d70','WorkFirst Employment Services','employment',NULL,'555-0213',NULL,NULL,'https://example.org/workfirst-employment-services','720 Sample Ave','Springfield','00000','Mon–Fri 9–5',NULL,'Job readiness, résumé help, fair-chance employers.','English, Spanish',0,1,NULL,NULL,NULL,'Job-readiness classes, résumé and interview help and a network of fair-chance employers who hire people with records. Paid work-experience placements for people in recovery.','employment,peer_support,spanish_speaking',NULL,'adults,justice_involved','Orientation every Monday at 9am; no referral needed.','Free.',1,'2026-08-08','Sample resource (fictional)','2026-09-26T23:20:32.008Z','2026-09-26T23:20:32.008Z');
INSERT INTO "resources"("id","name","category","organization","phone","fax","email","website","address","city","zip","hours","eligibility","services","languages","accepts_medicaid","accepts_uninsured","mat_offered","capacity_notes","contact_person","summary","service_tags","levels_of_care","populations","intake_process","cost_notes","is_active","last_verified_at","notes","created_at","updated_at") VALUES('ee1e7037-94b4-49b8-a89f-c643b9fa1f55','Recovery Café','recovery_community',NULL,'555-0214',NULL,NULL,'https://example.org/recovery-caf-','760 Sample Ave','Springfield','00000','Daily 10–6',NULL,'Peer-led recovery community; meetings and meals.','English',0,1,NULL,NULL,NULL,'A membership-based recovery community: meals, meetings, art and music groups, and peer recovery coaches. Members commit to 24 hours of sobriety before each visit and to a weekly recovery circle.','peer_support,walk_in,aftercare,employment',NULL,'adults,lgbtq,unhoused','Drop in for a tour any day; membership starts after a short orientation.','Free; members volunteer a few hours a month.',1,'2026-09-20','Sample resource (fictional)','2026-09-26T23:20:32.014Z','2026-09-26T23:20:32.014Z');
CREATE TABLE resource_photos (
  id TEXT PRIMARY KEY,
  resource_id TEXT NOT NULL REFERENCES resources(id) ON DELETE CASCADE,
  caption TEXT,
  content_type TEXT NOT NULL,
  bytes INTEGER NOT NULL DEFAULT 0,
  width INTEGER, height INTEGER,
  -- Nullable: an attachment row reaches a device before its bytes do. Attachments are fetched by id once
  -- the rows have landed, because inlining every photo made a sync payload the phone could not parse.
  data_b64 TEXT,                       -- downscaled picture (JPEG/PNG/WebP), base64
  thumb_b64 TEXT,                       -- small JPEG thumbnail for lists, base64
  sort_order INTEGER NOT NULL DEFAULT 0,
  uploaded_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE policy_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  category TEXT NOT NULL CHECK (category IN ('policy','procedure','contract')),
  description TEXT,
  effective_date TEXT,
  expires_at TEXT,
  filename TEXT,
  content_type TEXT,
  bytes INTEGER NOT NULL DEFAULT 0,
  file_b64 TEXT,
  search_text TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  uploaded_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE referrals (
  id TEXT PRIMARY KEY,
  client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  resource_id TEXT NOT NULL REFERENCES resources(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  referred_at TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  urgency TEXT DEFAULT 'routine',
  appointment_at TEXT,
  admitted_at TEXT,
  closed_at TEXT,
  outcome_enc TEXT,                    -- free text about a named person's treatment: encrypted
  barrier_enc TEXT,
  warm_handoff INTEGER DEFAULT 0,
  consent_id TEXT REFERENCES consents(id) ON DELETE SET NULL,
  -- set when the consent this referral relied on is revoked, so the worker is told to stop sharing
  consent_revoked INTEGER NOT NULL DEFAULT 0,
  follow_up_due TEXT,
  outcome_recorded_at TEXT,
  episode_id TEXT REFERENCES episodes(id) ON DELETE SET NULL,
  notes_enc TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
