CREATE TABLE form_templates (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  category TEXT NOT NULL DEFAULT 'other',
  version TEXT,
  filename TEXT,                       -- original county form file (PDF/Word/image), optional
  content_type TEXT,
  bytes INTEGER NOT NULL DEFAULT 0,
  file_b64 TEXT,
  fields_json TEXT NOT NULL DEFAULT '[]', -- [{key,label,type,required,options,autofill,help}]
  instructions TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  uploaded_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
INSERT INTO "form_templates"("id","name","description","category","version","filename","content_type","bytes","file_b64","fields_json","instructions","is_active","uploaded_by","created_at","updated_at") VALUES('51295662-0e9b-4ac9-8d74-8e44427f67e4','Consent for Release of Information (42 CFR Part 2)','Authorizes the program to share SUD treatment information with a named provider or agency.','consent_release','2026-01','SC-100.pdf','application/pdf',3722,'','[{"key":"client_name","label":"Client name","type":"text","required":true,"autofill":"client.full_name"},{"key":"dob","label":"Date of birth","type":"date","autofill":"client.dob"},{"key":"client_code","label":"Client ID","type":"text","autofill":"client.client_code"},{"key":"sec_release","label":"Release","type":"section"},{"key":"recipient","label":"Information may be released to (name / agency)","type":"text","required":true},{"key":"purpose","label":"Purpose of the disclosure","type":"textarea","required":true},{"key":"info","label":"Information to be released","type":"select","options":["Referral summary","Diagnosis and MAT status","Attendance and progress","Full record"],"required":true},{"key":"expires","label":"This consent expires on","type":"date","required":true},{"key":"redisclosure","label":"I understand that my records are protected under 42 CFR Part 2 and cannot be re-disclosed without my written consent.","type":"checkbox"},{"key":"revoke","label":"I understand I may revoke this consent at any time except to the extent action has been taken in reliance on it.","type":"checkbox"},{"key":"sec_sign","label":"Signatures","type":"section"},{"key":"client_sig","label":"Client signature","type":"signature","required":true},{"key":"date","label":"Date","type":"date","autofill":"today","required":true},{"key":"witness","label":"Witness / navigator","type":"text","autofill":"worker.name"}]','Review each line with the client. Part 2 consents must name who receives the information, what is shared and why, and when the consent expires.',1,'367ae0fb-aefb-42bb-b187-eadf097f3a93','2026-09-26T23:20:32.057Z','2026-09-26T23:20:32.057Z');
INSERT INTO "form_templates"("id","name","description","category","version","filename","content_type","bytes","file_b64","fields_json","instructions","is_active","uploaded_by","created_at","updated_at") VALUES('0d37eea8-5388-4344-a011-54d06f6504e0','Navigation Intake & Screening Sheet','First-contact intake for the county SUD navigation program.','intake_screening','2026-01','SC-101.pdf','application/pdf',4360,'','[{"key":"sec_id","label":"Identification","type":"section"},{"key":"client_name","label":"Client name","type":"text","required":true,"autofill":"client.full_name"},{"key":"preferred_name","label":"Preferred name","type":"text","autofill":"client.preferred_name"},{"key":"dob","label":"Date of birth","type":"date","autofill":"client.dob"},{"key":"phone","label":"Best phone number","type":"text","autofill":"client.phone"},{"key":"address","label":"Where are you staying?","type":"text","autofill":"client.address"},{"key":"insurance","label":"Insurance","type":"text","autofill":"client.insurance"},{"key":"sec_use","label":"Substance use","type":"section"},{"key":"substance","label":"Primary substance","type":"text","autofill":"client.primary_substance"},{"key":"last_use","label":"Last use","type":"date"},{"key":"od_year","label":"Overdose in the past 12 months","type":"checkbox"},{"key":"naloxone","label":"Has naloxone","type":"checkbox"},{"key":"mat_interest","label":"Interested in medication (MAT)?","type":"select","options":["Yes","No","Not sure","Already on MAT"]},{"key":"sec_needs","label":"Immediate needs","type":"section"},{"key":"needs","label":"What would help most this week?","type":"textarea"},{"key":"safety","label":"Safety concerns (self, others, domestic violence)","type":"textarea"},{"key":"navigator","label":"Navigator","type":"text","autofill":"worker.name"},{"key":"date","label":"Date","type":"date","autofill":"today"}]','Complete at the first meeting. Leave blank anything the client does not want to answer.',1,'367ae0fb-aefb-42bb-b187-eadf097f3a93','2026-09-26T23:20:32.057Z','2026-09-26T23:20:32.057Z');
INSERT INTO "form_templates"("id","name","description","category","version","filename","content_type","bytes","file_b64","fields_json","instructions","is_active","uploaded_by","created_at","updated_at") VALUES('413305b9-c4c6-4bf2-bda0-f6a557cb8fc4','Client Assistance Request (Transportation / Basic Needs)','Request to spend client-assistance funds (bus passes, IDs, phones, emergency motel).','assistance_request','2026-01','SC-102.pdf','application/pdf',2965,'','[{"key":"client_name","label":"Client name","type":"text","required":true,"autofill":"client.full_name"},{"key":"client_code","label":"Client ID","type":"text","autofill":"client.client_code"},{"key":"date","label":"Date","type":"date","autofill":"today"},{"key":"item","label":"Item / service requested","type":"select","options":["Bus pass","Ride to appointment","State ID fee","Birth certificate","Prepaid phone","Emergency motel","Hygiene / clothing","Other"],"required":true},{"key":"amount","label":"Estimated cost ($)","type":"number","required":true},{"key":"vendor","label":"Vendor","type":"text"},{"key":"justification","label":"How this supports the recovery plan","type":"textarea","required":true},{"key":"urgent","label":"Urgent (needed within 24 hours)","type":"checkbox"},{"key":"navigator","label":"Requested by","type":"text","autofill":"worker.name","required":true},{"key":"supervisor","label":"Supervisor approval (name)","type":"signature"}]','Attach the receipt to the expenditure after purchase. Requests over $250 need supervisor approval before spending.',1,'367ae0fb-aefb-42bb-b187-eadf097f3a93','2026-09-26T23:20:32.057Z','2026-09-26T23:20:32.057Z');
CREATE TABLE client_forms (
  id TEXT PRIMARY KEY,
  client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  template_id TEXT REFERENCES form_templates(id) ON DELETE SET NULL,
  template_name TEXT NOT NULL,         -- snapshot so the record survives template changes
  fields_json TEXT NOT NULL DEFAULT '[]', -- snapshot of the field definitions used
  values_enc TEXT NOT NULL,            -- encrypted JSON {key: value} (PHI)
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','completed','void')),
  completed_at TEXT,
  completed_by TEXT REFERENCES users(id),
  created_by TEXT NOT NULL REFERENCES users(id),
  notes_enc TEXT,                      -- free text about this client's form: encrypted
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at TEXT
);
